// Parse canary output and forward summary for optional Telegram notification.
// Output is plain text; extract the Done/DRY-RUN summary line.
const stdout = $input.item.json.stdout || '';
const stderr = $input.item.json.stderr || '';
const exitCode = $input.item.json.exitCode ?? -1;

const summaryMatch = stdout.match(/(Done\..+|DRY-RUN.+)/);
const summary = summaryMatch ? summaryMatch[1] : 'Canary run complete (no summary line)';

return [{
  json: {
    summary,
    exit_code: exitCode,
    has_errors: stderr.includes('[ERROR]') || exitCode !== 0,
    stderr_preview: stderr.slice(0, 300),
    ts: new Date().toISOString(),
  }
}];
